-- risk_appetite_metric: Board-approved risk appetite metric with amber/red thresholds and its latest value
CREATE TABLE risk_appetite_metric (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
