  row_version                  integer NOT NULL DEFAULT 1,
  legal_entity_id              uuid NOT NULL,
  metric_code                  varchar(64) NOT NULL,
  name                         varchar(160) NOT NULL,
  unit                         varchar(16) NOT NULL,
  threshold_amber              numeric(18,10) NOT NULL,
  threshold_red                numeric(18,10) NOT NULL,
  current_value                numeric(18,10),
  status                       varchar(40) NOT NULL DEFAULT 'GREEN' CHECK (status IN ('GREEN', 'AMBER', 'RED')),
  measured_at                  timestamptz,
